export async function fetchApiPerformanceAnnualized(ctx, params) {
    return ctx.api.fetchJson("/v1/performance/annualized", {
        query: {
            period: params?.period,
            address: params?.address,
        },
    });
}
export async function fetchApiPerformanceSnapshots(ctx, params) {
    return ctx.api.fetchJson("/v1/performance/snapshots", {
        query: {
            period: params?.period,
            address: params?.address,
        },
    });
}
